const business = function classifierResult({ text }) {
  let parsed;
  try {
    const raw = text.trim();
    try { parsed = JSON.parse(raw); }
    catch { parsed = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); }
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('Expected an object');
  } catch {
    parsed = { route: 'general', priority: 'medium', summary: 'Unable to classify' };
  }
  const route = typeof parsed.route === 'string' ? parsed.route.toLowerCase() : '';
  const priority = typeof parsed.priority === 'string' ? parsed.priority.toLowerCase() : '';
  return {
    response: {
      received: true,
      route: ['support', 'sales', 'technical', 'general'].includes(route) ? route : 'general',
      priority: ['high', 'medium', 'low'].includes(priority) ? priority : 'medium',
      summary: typeof parsed.summary === 'string' ? parsed.summary : '',
    },
  };
}

return $input.all().map((item, index) => { const result = business({text:item.json.content?.[0]?.text}); return {json: result, pairedItem: {item: index}}; });

const business = function classifierRequest({ body }) {
  if (body === null || typeof body !== 'object' || !Object.hasOwn(body, 'request')) {
    throw new Error('Provide the request to classify in the request field');
  }
  return { requestJson: JSON.stringify(body.request) };
}

return $input.all().map((item, index) => { const result = business({body:item.json.body}); return {json: result, pairedItem: {item: index}}; });
